function upgradeGroupLandingPages(app){
 const main=app.querySelector('main.portal'),holder=main?.querySelector('.portal-section-panels');if(!main||!holder||holder.dataset.fullPageTiles==='true')return;holder.dataset.fullPageTiles='true';
 holder.querySelectorAll('.portal-group-landing').forEach(landing=>{const groupTitle=landing.querySelector('.portal-group-heading h2')?.textContent?.trim()||'Menu',grid=landing.querySelector('.portal-group-grid');if(!grid)return;[...grid.querySelectorAll(':scope > .portal-group-card')].forEach(card=>{const heading=card.querySelector(':scope > h2, :scope > .feature-head h2'),oldButton=heading?.querySelector('.staff-tool-tile'),title=(oldButton?.textContent||heading?.textContent||'Section').trim();if(groupTitle==='Staff'&&title==='My staff profile'){card.remove();return}const tile=document.createElement('button');tile.type='button';tile.className='portal-landing-tile';tile.textContent=title;const page=document.createElement('section');page.className='portal-group-tool-page';page.hidden=true;page.innerHTML=`<button type="button" class="button secondary portal-group-back">← Back to ${groupTitle}</button><div class="portal-group-tool-content"></div>`;if(heading)heading.textContent=title;card.classList.remove('staff-tool-card','staff-tool-open','portal-group-card');page.querySelector('.portal-group-tool-content').append(card);holder.append(page);tile.onclick=()=>{landing.hidden=true;page.hidden=false;page.scrollIntoView({behavior:'smooth',block:'start'})};page.querySelector('.portal-group-back').onclick=()=>{page.hidden=true;landing.hidden=false;landing.scrollIntoView({behavior:'smooth',block:'start'})};grid.append(tile)})});
 main.querySelectorAll('.portal-section-nav > button').forEach(button=>button.addEventListener('click',()=>holder.querySelectorAll('.portal-group-tool-page').forEach(page=>page.hidden=true)));
}

