let npiSearchTimer;document.addEventListener('input',event=>{if(!event.target.matches?.('[data-npi-search]'))return;clearTimeout(npiSearchTimer);const input=event.target,term=input.value.trim(),root=input.closest('section,details,label')?.parentElement||document,results=root.querySelector('[data-npi-results]');if(!results)return;if(term.length<3){results.innerHTML='';return}results.textContent='Searching the CMS NPPES registry…';npiSearchTimer=setTimeout(async()=>{const entity=root.querySelector('[data-npi-entity]')?.value||'individual',digits=term.replace(/\D/g,''),params=new URLSearchParams({version:'2.1',limit:'20'});if(digits.length===10)params.set('number',digits);else if(entity==='organization')params.set('organization_name',`${term}*`);else params.set('last_name',`${term}*`);try{const data=await fetch(`https://npiregistry.cms.hhs.gov/api/?${params}`).then(response=>{if(!response.ok)throw new Error('Registry request failed');return response.json()});results.innerHTML=(data.results||[]).map(record=>{const basic=record.basic||{},name=record.enumeration_type==='NPI-2'?basic.organization_name:[basic.first_name,basic.last_name].filter(Boolean).join(' ');return `<button type="button" class="registry-result" data-select-npi="${h(record.number)}"><b>${h(name||'Name not supplied')}</b><small>NPI ${h(record.number)} · ${h(record.enumeration_type||'')}</small></button>`}).join('')||'<p>No matching NPPES records.</p>'}catch{results.innerHTML='<p>CMS NPPES search is unavailable. Enter the identifier manually.</p>'}},250)});document.addEventListener('click',event=>{const result=event.target.closest?.('[data-select-npi]');if(!result)return;const scope=result.closest('form,section'),field=scope?.querySelector('[name="npi"]');if(field)field.value=result.dataset.selectNpi;scope?.querySelector('[data-npi-results]')?.replaceChildren()});
