  renderVerifiedMethods=()=>{app.innerHTML=`<main class="auth-gate"><section class="auth-card"><img class="portal-logo" src="/assets/images/healthcarology-logo.png" alt="Healthcarology"><p class="eyebrow">Secure sign in</p><h1>${verified.length>1?"Choose a verification method":"Verify your identity"}</h1><p>${verified.length>1?"Select one of the authentication methods already connected to your account.":"Only one authentication method is currently connected to this account."}</p><div class="mfa-methods">${verified.map(factor=>`<button type="button" class="mfa-method" data-factor="${h(factor.id)}"><strong>${factor.factor_type==="phone"?"Phone verification":h(factor.friendly_name||"Authenticator app")}</strong><small>${factor.factor_type==="phone"?h(factor.phone||"Registered phone"):"Six-digit authenticator code"}</small></button>`).join("")}</div>${verified.length===1?'<p class="muted">Complete verification using the enrolled method shown above.</p>':''}<p id="mfa-message"></p></section></main>`;app.querySelectorAll("[data-factor]").forEach(button=>button.addEventListener("click",()=>{const factor=verified.find(item=>item.id===button.dataset.factor);verifyFactor(factor,factor.factor_type==="phone"&&factor.friendly_name?.includes("WhatsApp")?"whatsapp":undefined)}))};
  if(verified.length){renderVerifiedMethods();return false}
  app.innerHTML=`<main class="auth-gate"><section class="auth-card auth-card-wide"><img class="portal-logo" src="/assets/images/healthcarology-logo.png" alt="Healthcarology"><p class="eyebrow">First-login security setup</p><h1>Choose your authentication method</h1><p>This additional check protects clinical and administrative information. You can add another method later.</p><form id="mfa-method-choice"><div class="mfa-methods"><label class="mfa-method"><input type="radio" name="method" value="totp" checked><span><strong>Authenticator app</strong><small>Google, Microsoft, Oracle, Authy, or another TOTP-compatible app</small></span></label><label class="mfa-method"><input type="radio" name="method" value="sms"><span><strong>Text message (SMS)</strong><small>Receive a six-digit code on your phone</small></span></label><label class="mfa-method"><input type="radio" name="method" value="whatsapp"><span><strong>WhatsApp</strong><small>Receive a six-digit code through WhatsApp</small></span></label></div><label id="authenticator-choice">Authenticator application<select name="provider"><option>Google Authenticator</option><option>Microsoft Authenticator</option><option>Oracle Mobile Authenticator</option><option>Authy</option><option>Other compatible authenticator</option></select></label><label id="phone-choice" hidden>Mobile phone number<input type="tel" name="phone" autocomplete="tel" placeholder="International format, e.g. +243..."></label><label class="mfa-remember"><input type="checkbox" name="remember_device"> Remember this device for 30 days</label><button class="button">Continue setup</button></form><p id="mfa-message"></p></section></main>`;
  const methodForm=app.querySelector("#mfa-method-choice"),phoneChoice=app.querySelector("#phone-choice"),authenticatorChoice=app.querySelector("#authenticator-choice");methodForm.onchange=()=>{const phone=methodForm.method.value!=="totp";phoneChoice.hidden=!phone;phoneChoice.querySelector("input").required=phone;authenticatorChoice.hidden=phone};methodForm.onsubmit=async e=>{e.preventDefault();if(!await refreshMfaSession(supabase,app))return;const form=new FormData(e.target),rememberDevice=form.get("remember_device")==="on",method=form.get("method"),isPhone=method!=="totp",enrollment=await supabase.auth.mfa.enroll(isPhone?{factorType:"phone",friendlyName:`Healthcarology ${method==="whatsapp"?"WhatsApp":"SMS"}`,phone:form.get("phone")}:{factorType:"totp",friendlyName:form.get("provider")});if(enrollment.error){app.querySelector("#mfa-message").textContent=enrollment.error.message;return}const factor=enrollment.data;if(isPhone){await verifyFactor(factor,method==="whatsapp"?"whatsapp":undefined);return}app.innerHTML=`<main class="auth-gate"><section class="auth-card"><img class="portal-logo" src="/assets/images/healthcarology-logo.png" alt="Healthcarology"><p class="eyebrow">Authenticator setup</p><h1>Connect ${h(form.get("provider"))}</h1><p>Scan this standard TOTP QR code with the application you selected.</p><img class="mfa-qr" src="${h(factor.totp.qr_code)}" alt="Authenticator QR code"><details><summary>Enter a setup key instead</summary><code class="secret">${h(factor.totp.secret)}</code></details><form id="mfa-enroll"><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" placeholder="Six-digit code" required><button class="button">Activate and continue</button></form><p id="mfa-message"></p></section></main>`;app.querySelector("form").onsubmit=async event=>{event.preventDefault();const challenge=await supabase.auth.mfa.challenge({factorId:factor.id});if(challenge.error){app.querySelector("#mfa-message").textContent=challenge.error.message;return}const result=await supabase.auth.mfa.verify({factorId:factor.id,challengeId:challenge.data.id,code:new FormData(event.target).get("code")}),sessionError=await persistMfaSession(supabase,result);app.querySelector("#mfa-message").textContent=sessionError?.message||"MFA activated";if(!sessionError){rememberMfaVerification(userId,rememberDevice);location.reload()}}};return false;
