export async function requirePasswordChange(supabase,app,session){
 if(session.user.app_metadata?.must_change_password!==true)return true;
 app.innerHTML=`<main class="auth-gate"><section class="auth-card"><img class="portal-logo" src="/assets/images/healthcarology-logo.png" alt="Healthcarology"><h1>Create a permanent password</h1><p>The temporary password cannot be used to enter the platform.</p><form><input type="password" name="new_password" minlength="12" placeholder="New password" required><input type="password" name="confirm_password" minlength="12" placeholder="Confirm password" required><button class="button">Change password</button></form><p id="password-message"></p></section></main>`;
 app.querySelector("form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),password=f.get("new_password");if(password!==f.get("confirm_password")){app.querySelector("#password-message").textContent="Passwords do not match.";return}const {data,error}=await supabase.functions.invoke("complete-password-change",{body:{password}});app.querySelector("#password-message").textContent=error?.message||data?.error||"Password changed.";if(!error&&!data?.error)location.reload()};return false;
}

function heatmapCard(rows=[]){
  const max=Math.max(1,...rows.map(x=>Number(x.value)||0));
  return card("Health heat map",`<p class="muted">Aggregated jurisdiction metrics only; patient identities are not displayed.</p><div class="heatmap">${rows.map(x=>{const level=Math.max(1,Math.ceil((Number(x.value)||0)/max*5));return `<div class="heat-cell heat-${level}" title="${h(x.metric_label)}: ${h(x.value)}"><b>${h(x.geographic_label)}</b><span>${h(x.value)}</span><small>${h(x.metric_label)}</small></div>`}).join("")||'<p>No authorized aggregate observations are available.</p>'}</div>`);
}

async function commonData(supabase,facilityId){
  const [heat,threads,communities,groups,tickets]=await Promise.all([
    facilityId?supabase.from("health_heatmap_observations").select("id,metric_label,geographic_label,value,period_start,period_end").eq("facility_id",facilityId).order("period_end",{ascending:false}).limit(30):supabase.from("health_heatmap_observations").select("id,metric_label,geographic_label,value,period_start,period_end").order("period_end",{ascending:false}).limit(30),
    supabase.from("message_threads").select("id,subject,thread_type,created_at").order("created_at",{ascending:false}).limit(10),
    supabase.from("communities").select("id,title,description,visibility,status").eq("status","active").order("title"),
    supabase.from("support_groups").select("id,name,group_type").order("name"),
    supabase.from("support_tickets").select("id,ticket_number,subject,priority,status,created_at,directed_group_id").order("created_at",{ascending:false}).limit(20)
  ]);return{heat:heat.data||[],threads:threads.data||[],communities:communities.data||[],groups:groups.data||[],tickets:tickets.data||[]}
}

function messageCard(threads){return card("Messages",`<form id="message-thread-form"><label>Subject<input name="subject" required></label><label>Send to<select name="thread_type"><option value="direct">Specific person</option><option value="group">Group</option><option value="facility_broadcast">All facility members</option></select></label><label>Recipient user IDs<input name="recipient_ids" placeholder="Comma-separated IDs for person or group"></label><label>Message<textarea name="body" required></textarea></label><button class="button">Send</button><p class="form-result"></p></form><div class="compact-list">${threads.map(x=>`<div class="row"><span><b>${h(x.subject)}</b><small>${h(x.thread_type)} · ${date(x.created_at)}</small></span></div>`).join("")||"No message threads."}</div>`)}
