async function wireCommon(supabase,app,facilityId){
  const user=(await supabase.auth.getUser()).data.user;
  app.querySelector("#message-thread-form")?.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.target),threadType=f.get("thread_type"),subject=f.get("subject"),body=f.get("body");const created=await supabase.from("message_threads").insert({facility_id:facilityId||null,subject,thread_type:threadType,created_by:user.id}).select("id").single();if(created.error){e.target.querySelector(".form-result").textContent=created.error.message;return}let ids=String(f.get("recipient_ids")||"").split(",").map(x=>x.trim()).filter(Boolean);if(threadType==="facility_broadcast"&&facilityId){const m=await supabase.from("facility_memberships").select("user_id").eq("facility_id",facilityId).eq("active",true);ids=(m.data||[]).map(x=>x.user_id)}if(ids.length)await supabase.from("message_participants").insert([...new Set(ids.filter(x=>x!==user.id))].map(user_id=>({thread_id:created.data.id,user_id})));const sent=await supabase.from("messages").insert({thread_id:created.data.id,sender_user_id:user.id,body});e.target.querySelector(".form-result").textContent=sent.error?.message||"Message sent."});
  app.querySelector("#community-form")?.addEventListener("submit",async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target));body.created_by=user.id;const r=await supabase.from("communities").insert(body);e.target.querySelector(".form-result").textContent=r.error?.message||"Community created."});
  app.querySelectorAll("[data-community]").forEach(b=>b.onclick=async()=>{if(!confirm(`Join this ${b.dataset.visibility} community?`))return;const r=await supabase.from("community_memberships").insert({community_id:b.dataset.community,user_id:user.id,role:"member",status:b.dataset.visibility==="public"?"active":"pending"});alert(r.error?.message||"Membership request recorded.")});
  app.querySelector("#ticket-form")?.addEventListener("submit",async e=>{e.preventDefault();const f=new FormData(e.target),ticket=await supabase.from("support_tickets").insert({facility_id:facilityId||null,directed_group_id:f.get("directed_group_id"),subject:f.get("subject"),priority:f.get("priority"),created_by:user.id}).select("id").single();if(ticket.error){e.target.querySelector(".form-result").textContent=ticket.error.message;return}const msg=await supabase.from("support_ticket_messages").insert({ticket_id:ticket.data.id,sender_user_id:user.id,body:f.get("message")});e.target.querySelector(".form-result").textContent=msg.error?.message||"Support ticket created."});
}

