  app.querySelectorAll("[data-fulfillment-status]").forEach(select=>select.onchange=async()=>{const body={status:select.value,updated_at:new Date().toISOString()};if(select.value==="awaiting")body.awaiting_at=new Date().toISOString();if(select.value==="dispensed")body.dispensed_at=new Date().toISOString();const r=await supabase.from("prescription_fulfillments").update(body).eq("id",select.dataset.fulfillmentStatus);if(r.error)alert(r.error.message)});
